import re

# Assume the helper functions mentioned in the prompt are available:
# node_by_title(doc, title) -> node dict
# node_by_id(doc, node_id) -> node dict
# children(doc, node) -> list of child node dicts
# table_rows(node) -> list of (row_index, {column_name: cell_str})


def _safe_int(s, src=None):
    """Convert a cell to int, return None if empty or invalid."""
    try:
        return int(s)
    except (ValueError, TypeError):
        return None


def entities(doc, scope):
    """Return all product entities in the scope."""
    scope_node = node_by_title(doc, scope)
    prod_node = None
    for ch in children(doc, scope_node):
        if ch["kind"] == "table" and ch["title"].endswith(": Products"):
            prod_node = ch
            break
    if not prod_node:
        return []

    lst = []
    for idx, row in table_rows(prod_node):
        pid = row["product"]
        lst.append(
            {
                "id": pid,
                "description": f"{pid}: group {row['group']}, sub-group "
                f"{row['sub-group']}, storage {row['storage location']}, "
                f"{row['kg per unit']} kg, opening stock {row['opening stock']}",
            }
        )
    return lst


def recorded_end(doc, scope):
    """Return last day number recorded in the ledger."""
    scope_node = node_by_title(doc, scope)
    ledger_node = None
    for ch in children(doc, scope_node):
        if ch["kind"] == "table" and ch["title"].endswith(": Daily ledger"):
            ledger_node = ch
            break
    if not ledger_node:
        return None
    last_day = None
    for idx, row in table_rows(ledger_node):
        d = _safe_int(row["day"])
        if d is not None and (last_day is None or d > last_day):
            last_day = d
    return last_day


def _parse_order_book_row(node, idx, row):
    """Parse a single row of an Order book table."""
    product = row["product"]
    day = _safe_int(row["day"])
    if day is None:
        return None

    inputs = []

    if "planned production" in row and row["planned production"]:
        qty = _safe_int(row["planned production"])
        if qty is not None and qty > 0:
            inputs.append(
                {
                    "id": f"{product}-planned-production-day{day}",
                    "time": day,
                    "kind": "planned_production",
                    "entities": [product],
                    "fields": {"quantity": qty},
                    "src": [[node["node_id"], idx, ["planned production"]]],
                }
            )
    if "ordered" in row and row["ordered"]:
        qty = _safe_int(row["ordered"])
        if qty is not None and qty > 0:
            inputs.append(
                {
                    "id": f"{product}-planned-order-day{day}",
                    "time": day,
                    "kind": "planned_order",
                    "entities": [product],
                    "fields": {"quantity": qty},
                    "src": [[node["node_id"], idx, ["ordered"]]],
                }
            )
    return inputs


def inputs(doc, scope):
    """Return the list of input records for the scope."""
    scope_node = node_by_title(doc, scope)
    pid_match = re.search(r"Plant (\d+)", scope)
    plant_id = pid_match.group(1) if pid_match else None

    all_inputs = []

    # 1. Initial opening stock
    prod_node = None
    for ch in children(doc, scope_node):
        if ch["kind"] == "table" and ch["title"].endswith(": Products"):
            prod_node = ch
            break
    if prod_node:
        for idx, row in table_rows(prod_node):
            pid = row["product"]
            open_stock = _safe_int(row["opening stock"])
            if open_stock is not None:
                all_inputs.append(
                    {
                        "id": f"{pid}-opening-stock",
                        "time": None,
                        "kind": "initial_state",
                        "entities": [pid],
                        "fields": {"opening_stock": open_stock},
                        "src": [[prod_node["node_id"], idx, ["opening stock"]]],
                    }
                )

    # 2. Daily production & orders from ledger
    ledger_node = None
    for ch in children(doc, scope_node):
        if ch["kind"] == "table" and ch["title"].endswith(": Daily ledger"):
            ledger_node = ch
            break
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            pid = row["product"]
            day = _safe_int(row["day"])
            if day is None:
                continue

            produced_val = _safe_int(row["produced"])
            if produced_val is not None and produced_val > 0:
                all_inputs.append(
                    {
                        "id": f"{pid}-production-day{day}",
                        "time": day,
                        "kind": "production",
                        "entities": [pid],
                        "fields": {"quantity": produced_val},
                        "src": [[ledger_node["node_id"], idx, ["produced"]]],
                    }
                )

            ordered_val = _safe_int(row["ordered"])
            if ordered_val is not None and ordered_val > 0:
                all_inputs.append(
                    {
                        "id": f"{pid}-sales-order-day{day}",
                        "time": day,
                        "kind": "sales_order",
                        "entities": [pid],
                        "fields": {"quantity": ordered_val},
                        "src": [[ledger_node["node_id"], idx, ["ordered"]]],
                    }
                )

    # 3. Future planned orders from any Order book tables
    for ch in children(doc, scope_node):
        if ch["kind"] == "table" and "Order book" in ch["title"]:
            for idx, row in table_rows(ch):
                row_inputs = _parse_order_book_row(ch, idx, row)
                if row_inputs:
                    all_inputs.extend(row_inputs)

    # 4. Dispatch capacity constant – handled in params()
    return all_inputs


def _parse_event_line(line):
    """Parse an event line to extract day, kind and (optionally) product."""
    day_match = re.search(r"Day (\d+)", line)
    if not day_match:
        return None, None, None
    day = int(day_match.group(1))

    # Product may appear after colon
    prod_match = re.search(r":\s*(?P<prod>[\w\-]+)", line)
    product = prod_match.group("prod") if prod_match else None

    if "dispatch capacity reached" in line:
        return day, "dispatch_capacity_reached", product
    if "runs out of stock" in line:
        return day, "runs_out_of_stock", product
    if "fully backordered" in line:
        return day, "order_fully_backordered", product
    if "backlog cleared" in line:
        return day, "backlog_cleared", product
    if "ships in full" in line:
        return day, "order_shipped_in_full", product
    return day, "unknown_event", product


def outcomes(doc, scope):
    """Return the list of outcome records for the scope."""
    scope_node = node_by_title(doc, scope)

    out = []

    # 1. Ledger results: shipped, backordered, stock
    ledger_node = None
    for ch in children(doc, scope_node):
        if ch["kind"] == "table" and ch["title"].endswith(": Daily ledger"):
            ledger_node = ch
            break
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            pid = row["product"]
            day = _safe_int(row["day"])
            if day is None:
                continue
            for kind in ("shipped", "backordered", "stock"):
                val = _safe_int(row.get(kind, ""))
                if val is None:
                    continue
                out.append(
                    {
                        "time": day,
                        "kind": kind,
                        "entities": [pid],
                        "value": val,
                        "src": [[ledger_node["node_id"], idx, [kind]]],
                    }
                )

    # 2. Events list
    for ch in children(doc, scope_node):
        if ch["kind"] == "list" and "Events" in ch["title"]:
            for idx, line in enumerate(ch["lines"]):
                day, kind, prod = _parse_event_line(line)
                if day is None or kind is None:
                    continue
                ents = [prod] if prod else []
                out.append(
                    {
                        "time": day,
                        "kind": kind,
                        "entities": ents,
                        "value": None,
                        "src": [[ch["node_id"], idx]],
                    }
                )
            break

    return out


def params(doc, scope):
    """Return constant parameters stated in the scope."""
    scope_node = node_by_title(doc, scope)

    # Dispatch capacity is written in the scope node's text
    if "Daily dispatch capacity:" in scope_node["text"]:
        m = re.search(r"Daily dispatch capacity:\s*([\d,]+)" r"\s*kg", scope_node["text"])
        if m:
            cap = int(m.group(1).replace(",", ""))
            return {"dispatch_capacity": cap}
    return {}

