def _safe_int(val: Any) -> int | None:
    """Return int from a string or None if conversion fails or string is empty."""
    if not isinstance(val, str):
        return None
    val = val.strip()
    if val == "":
        return None
    try:
        return int(val)
    except ValueError:
        return None


